import{_ as a,o as n,c as l,a as p}from"./app.DkoUFz-u.js";const h=JSON.parse('{"title":"uglify-js","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/core/javascript/library/uglify.md","filePath":"frontend/core/javascript/library/uglify.md"}'),i={name:"frontend/core/javascript/library/uglify.md"};function e(_,s,c,o,t,r){return n(),l("div",null,[...s[0]||(s[0]=[p('<h1 id="uglify-js" tabindex="-1">uglify-js <a class="header-anchor" href="#uglify-js" aria-label="Permalink to &quot;uglify-js&quot;">​</a></h1><blockquote><p>UglifyJS是个包含JS解释器、代码最小化、压缩、美化的工具集，是前端开发打包的最常用工具之一。打包后的js,没有注释内容,没有空格且合并到一行,简化了函数参数和变量名</p></blockquote><ul><li>安装node.js</li><li>通过命令 npm install uglify-js -g</li><li>安装成功后，进入到需要压缩的js所在的目录。 然后通过uglifyjs main.js -m -o main.min.js进行压缩，该命令的意思就是把main.js压缩成 main.min.js。</li></ul><p>命令配置项</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">  -h, --help                  列出使用指南。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `--help options` 获取可用选项的详情。</span></span>\n<span class="line"><span class="__shiki_wvjl67">  -V, --version               打印版本号。</span></span>\n<span class="line"><span class="__shiki_wvjl67">  -p, --parse &lt;options&gt;       指定解析器配置选项:</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `acorn`  使用 Acorn 来解析。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `bare_returns`  允许在函数外return。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                              在压缩CommonJS模块或`.user.js `引擎调用被同步执行函数包裹的用户脚本 时会用到。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `expression`  不是解析文件，二是解析一段表达式 (例如解析JSON).</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `spidermonkey`  输入文件是 SpiderMonkey</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                              AST 格式 (JSON).</span></span>\n<span class="line"><span class="__shiki_wvjl67">  -c, --compress [options]    启用压缩（true/false）/指定压缩配置:</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `pure_funcs`  传一个函数名的列表，当这些函数返回值没被利用时，该函数会被安全移除。</span></span>\n<span class="line"><span class="__shiki_wvjl67">  -m, --mangle [options]       启用混淆（true/false）/指定混淆配置:</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `reserved`  不被混淆的名字列表。</span></span>\n<span class="line"><span class="__shiki_wvjl67">  --mangle-props [options]    混淆属性/指定压缩配置:</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `builtins`  混淆那些与标准JS全局变量重复的名字。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `debug`  添加debug前缀和后缀。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `domprops`  混淆那些鱼DOM属性名重复的名字。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `keep_quoted`  只混淆没括起来的属性名。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              </span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `regex`  只混淆匹配（该正则）的名字。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `reserved`  不需要混淆的名字的列表（即保留）。</span></span>\n<span class="line"><span class="__shiki_wvjl67">  -b, --beautify [options]    是否美化输出（true/false）/指定输出配置：</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `beautify`  默认是启用.</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `preamble`  预设的输出文件头部。你可以插入一段注释，比如版权信息。它不会被解析，但sourcemap会因此调整。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `quote_style`  括号类型:</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                              0 - auto自动</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                              1 - single单引号</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                              2 - double双引号</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                              3 - original跟随原码</span></span>\n<span class="line"><span class="__shiki_wvjl67">                              `wrap_iife`  把立即执行函数括起来。注意：你或许应禁用压缩配置中的`negate_iife`选项。 </span></span>\n<span class="line"><span class="__shiki_wvjl67"></span></span>\n<span class="line"><span class="__shiki_wvjl67"> -o, --output &lt;file&gt;         输出文件路径 (默认 STDOUT). 指定 `ast` 或</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `spidermonkey`的话分别是输出UglifyJS或SpiderMonkey AST。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --comments [filter]         保留版权注释。默认像Google Closure那样，保留包含&quot;@license&quot;或&quot;@preserve&quot;这样JSDoc风格的注释。你可以传以下的参数：</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                - &quot;all&quot; 保留全部注释</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                - 一个合适的正则，如 `/foo/` 或 `/^!/`，保留匹配到的注释。 </span></span>\n<span class="line"><span class="__shiki_wvjl67">                                注意，在启用压缩时，因为死代码被移除或压缩声明为一行，并非*所有*的注释都会被保留。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --config-file &lt;file&gt;        从此JSON文件读取 `minify()` 配置。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    -d, --define &lt;expr&gt;[=value] 定义全局变量。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --ie8                       支持IE8。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                等同于在`minify()`的`compress`、 `mangle` 和 `output`配置设置`ie8: true`。UglifyJS不会默认兼容IE8。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --keep-fnames               不要混淆、干掉的函数的名字。当代码依赖Function.prototype.name时有用。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --name-cache &lt;file&gt;         用来保存混淆map的文件。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --self                      把UglifyJS本身也构建成一个依赖包</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                (等同于`--wrap UglifyJS`)</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --source-map [options]      启用 source map（true/false）/指定sourcemap配置:</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `base` 根路径，用于计算输入文件的相对路径。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `content`  输入sourcemap。假如的你要编译的JS是另外的源码编译出来的。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                假如该sourcemap包含在js内，请指定&quot;inline&quot;。 </span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `filename`  输出文件的名字或位置。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `includeSources`  如果你要在sourcemap中加上源文件的内容作sourcesContent属性，就传这个参数吧。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `root`  此路径中的源码编译后会产生sourcemap.</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                `url`   如果指定此值，会添加sourcemap相对路径在`//#sourceMappingURL`中。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --timings                   在STDERR显示操作运行时间。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --toplevel                  压缩/混淆在最高作用域中声明的变量名。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --verbose                   打印诊断信息。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --warn                      打印警告信息。</span></span>\n<span class="line"><span class="__shiki_wvjl67">    --wrap &lt;name&gt;               把所有代码包裹在一个大函数中。让“exports”和“global”变量有效。</span></span>\n<span class="line"><span class="__shiki_wvjl67">                                你需要传一个参数来指定此模块的名字，以便浏览器引用。</span></span></code></pre></div>',5)])])}const v=a(i,[["render",e]]);export{h as __pageData,v as default};
